{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "florianbuetow-plugins",
  "version": "1.0.0",
  "description": "A collection of Claude Code plugins for software engineering workflows: SOLID principles analysis, system-level architecture principles analysis, software architecture quality assessment, application security analysis, expert-guided specification writing, specification-driven development, and distributed system tradeoff analysis.",
  "repository": "https://github.com/florianbuetow/claude-code",
  "owner": {
    "name": "Florian Buetow",
    "email": "2320560+florianbuetow@users.noreply.github.com"
  },
  "plugins": [
    {
      "name": "solid-principles",
      "description": "Analyze code for violations of the SOLID principles of object-oriented design (Single Responsibility, Open/Closed, Liskov Substitution, Interface Segregation, Dependency Inversion)",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/solid-principles",
      "category": "development"
    },
    {
      "name": "beyond-solid-principles",
      "description": "Analyze code and architecture for violations of ten system-level software design principles: Separation of Concerns, Single Responsibility (system-level), DRY, Law of Demeter, Loose Coupling / High Cohesion, Evolvability, Resilience, KISS, Principle of Least Surprise, and YAGNI",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/beyond-solid-principles",
      "category": "development"
    },
    {
      "name": "archibald",
      "description": "Software architecture quality assessment through structural smell detection, quantitative metrics analysis, antipattern identification, dependency structure evaluation, risk/trade-off analysis, and technical debt measurement.",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/archibald",
      "category": "development"
    },
    {
      "name": "spec-writer",
      "description": "An expert-guided skill for creating layered software specification documents for greenfield projects. Produces Vision, Business Requirements, Software Requirements, Architecture & Design, and Behavioral Spec & Test Verification documents.",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/spec-writer",
      "category": "development"
    },
    {
      "name": "spec-dd",
      "description": "Specification-driven development workflow skill. Orchestrates a spec-first discipline with advisory quality gates: behavioral specification, test specification, implementation specification, and alignment review.",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/spec-dd",
      "category": "development"
    },
    {
      "name": "explain-system-tradeoffs",
      "description": "Reverse-engineer distributed system tradeoffs from code, configuration, and architecture artifacts. Analyzes six axes: Consistency & Availability, Latency & Throughput, Data Distribution, Transaction Boundaries, Resilience & Failure Isolation, and Observability, Security & Cost.",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/explain-system-tradeoffs",
      "category": "development"
    },
    {
      "name": "kiss",
      "description": "Analyze code and architecture for unnecessary complexity, over-abstraction, and redundancy. Reports findings with severity ratings and concrete simplification suggestions.",
      "version": "1.0.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/kiss",
      "category": "development"
    },
    {
      "name": "appsec",
      "description": "Comprehensive application security toolbox for Claude Code. 62 skills across 8 frameworks (OWASP Top 10, OWASP API Top 10, STRIDE, PASTA, LINDDUN, MITRE ATT&CK, SANS/CWE Top 25, DREAD), red team simulation with 6 attacker personas plus consolidator, and interactive security education.",
      "version": "0.1.0",
      "author": {
        "name": "Florian Buetow",
        "email": "2320560+florianbuetow@users.noreply.github.com"
      },
      "source": "./plugins/appsec",
      "category": "security"
    }
  ]
}
